--- a/src/service.ts
+++ b/src/service.ts
@@ -1,8 +1,26 @@
 import type { ZoneRules } from "./zone.ts";
+import { parseZone, ZoneError } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

-/** Load the rules of a zone from the tz service. */
+const NAME_RE = /^[A-Za-z_]+(\/[A-Za-z0-9_+\-]+)+$/;
+
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
-}
+  if (!NAME_RE.test(name)) throw new RangeError(`invalid zone name: ${name}`);
+  let resp: Response;
+  try {
+    resp = await fetch(`${ZONES_URL}/${name}`);
+  } catch (e: unknown) {
+    throw new ZoneError(`tz service unavailable: ${(e as Error).message}`);
+  }
+  if (!resp.ok) {
+    throw new ZoneError(`tz service unavailable: ${resp.status} ${resp.statusText}`);
+  }
+  let body: unknown;
+  try {
+    body = await resp.json();
+  } catch {
+    throw new ZoneError("tz service unavailable: invalid JSON");
+  }
+  return parseZone(body);
+}
